package com.example.social.service;
import com.example.social.model.SocialPost;import com.example.social.repository.PostRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import java.time.LocalDateTime;import java.util.Map;
@Component public class ScheduledPostPublisher{private final PostRepository posts;private final KafkaTemplate<String,Object> kafka;@Value("${app.scheduling.fixed-delay-ms:30000}") private long delay;public ScheduledPostPublisher(PostRepository p,KafkaTemplate<String,Object> k){posts=p;kafka=k;}
 @Scheduled(fixedDelayString="${app.scheduling.fixed-delay-ms:30000}") public void publishDuePosts(){for(SocialPost p:posts.findByStatusAndScheduledAtBefore(SocialPost.Status.SCHEDULED,LocalDateTime.now())){try{kafka.send("post-publish-events",String.valueOf(p.getId()),Map.of("postId",p.getId(),"content",p.getContent(),"owner",p.getOwner().getEmail()));p.setStatus(SocialPost.Status.PUBLISH_REQUESTED);posts.save(p);}catch(Exception ex){/* Leave record scheduled; next poll retries. Add durable outbox in production. */}}}}
